from pathlib import Path
import pandas as pd, json, numpy as np
EXP=Path(__file__).resolve().parent
s=pd.read_csv(EXP/'results/summary.csv'); p=pd.read_csv(EXP/'results/paired_comparisons.csv'); m=pd.read_csv(EXP/'results/mechanism.csv'); iv=pd.read_csv(EXP/'results/interventions.csv'); a=pd.read_csv(EXP/'results/adversary_audit.csv'); pre=json.loads((EXP/'.runtime/preflight.json').read_text()); ca=json.loads((EXP/'.runtime/checkpoint_audit.json').read_text())
