add('## 疾病关系、对抗与图消息诊断'); add(); add(f"正确关系 10 折 OOF AUC={rm['oof_auc'][0]:.4f}±{rm['oof_auc'][1]:.4f}，跨站点 AUC={rm['cross_site_auc'][0]:.4f}±{rm['cross_site_auc'][1]:.4f}，同站点 AUC={rm['same_site_auc'][0]:.4f}±{rm['same_site_auc'][1]:.4f}，Brier={rm['brier'][0]:.4f}±{rm['brier'][1]:.4f}；10/10 折满足预设可靠性门槛。标签置乱 B7 的关系 OOF AUC={wm['oof_auc']:.4f}，跨站点 AUC={wm['cross_site_auc']:.4f}，接近机会水平。"); add(); add(f"B5 固定 checkpoint 的站点判别器 AUC={a.site_auc.mean():.4f}±{a.site_auc.std(ddof=0):.4f}，site loss={a.site_loss.mean():.6f}；接近机会水平说明站点关系难以由关系表示恢复，但不单独证明疾病泛化或对抗成功。"); add(); add(f"B5 最佳 checkpoint 的平均邻接绝对变化={m.edge_change.mean():.6f}，正消息范数={m.positive_norm.mean():.4f}，负消息范数={m.negative_norm.mean():.4f}，CORR 有界校正消息范数={m.delta_norm.mean():.4f}，相对 E1 表示范数比例={m.relative_delta_over_e1.mean():.4%}。关闭传播后 ACC 从 {iv[iv.intervention=='original'].acc.mean()*100:.4f}% 变为 {iv[iv.intervention=='prop_off'].acc.mean()*100:.4f}%；固定模型关闭边重加权没有产生硬预测变化，说明边变化进入了归一化 GCN 但量级不足以形成分类决策增量。"); add(); add('固定 B5 干预的指标和翻转数见 `results/interventions.csv`、`results/intervention_flips.csv`；关系/对抗 readback 见 `results/adversary_audit.csv`。正负交换产生 6 个测试预测翻转，但平均硬分类仍低于原始 B5；错误图干预没有产生硬翻转。'); add()
add('## 独立 checkpoint、随机性和竞争解释'); add(); add('独立审计重新加载 100 个 best checkpoint，逐折重算 ACC、Hard-AUC、Probability-AUC、SEN、SPE、BA、ASD-F1 及 TP/FN/FP/TN，100/100 通过且保存值与重算值最大差为 0。B1 完全不把关系辅助训练写入 CAM，结果与 B0 相同，排除了单纯关系参数容量收益。B2 的普通 CORR 相似度与 B5 没有形成疾病监督的独立优势。'); add(); add('主要竞争解释是：关系分数虽有 OOF 疾病信号，但在 `weight_decay=0.11` 的原始 GFR 中，边校准对归一化消息的影响很小；有界 signed DRMP 的非零消息进入 CAM，却没有提供超过 E1 的诊断信息。B8 正确/错误关系图 ACC 相同，不能把 pair BCE 或站点 AUC 当成患者关系身份的医学有效性。'); add()
add('## 局限与最终判断'); add(); add('本轮保留历史 `val=test`、CV 前标准化/RFE、transductive 871 节点图和单 seed=0，因此不能宣称无偏外部泛化或跨站点临床性能；十个折也不是十个独立外部数据集。站点关系只由 PHENO 的 `SITE_ID_*` one-hot 精确恢复，D²-ARG 不使用个体临床量表或文本语义。'); add(); add('**最终：工程 GO，科研 NO-GO。** D²-ARG 的疾病关系评分可被交叉拟合验证，但正确关系没有稳定超过 E1、错误患者图 B8，新增边校准和关系消息没有形成独立诊断增量；不建议以本轮结果作为 MICCAI 2027 第一创新模块的正向证据。若继续，应先改用独立验证/外部站点和真实可验证关系证据，避免在同一患者相似图上继续堆叠对抗或消息分支。'); add()
